"use client";

import { useNotifications } from "@/context/NotificationContext";
import { timeAgo } from "@/lib/time";

export default function NotificationsPage() {
  const { notifications, unreadCount, loading, markAllRead, markRead } = useNotifications();

  return (
    <div
      style={{
        background: "var(--bg-card)",
        borderRadius: "16px",
        border: "1px solid #2f3336",
        padding: "24px",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          gap: "12px",
          marginBottom: "20px",
          flexWrap: "wrap",
        }}
      >
        <div>
          <h1 style={{ color: "var(--text-main)", margin: 0 }}>Notifications</h1>
          <p style={{ color: "var(--text-muted)", margin: "8px 0 0 0" }}>
            {unreadCount > 0 ? `${unreadCount} unread notification${unreadCount === 1 ? "" : "s"}` : "You're all caught up."}
          </p>
        </div>

        {unreadCount > 0 && (
          <button
            onClick={markAllRead}
            style={{
              background: "var(--color-primary)",
              color: "#000",
              border: "none",
              padding: "10px 16px",
              borderRadius: "999px",
              fontWeight: "bold",
              cursor: "pointer",
            }}
          >
            Mark all read
          </button>
        )}
      </div>

      {loading ? (
        <div style={{ color: "var(--text-muted)", textAlign: "center", padding: "30px 0" }}>
          Loading notifications...
        </div>
      ) : notifications.length === 0 ? (
        <div style={{ color: "var(--text-muted)", textAlign: "center", padding: "30px 0" }}>
          No notifications yet.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          {notifications.map((notification) => (
            <button
              key={notification.id}
              type="button"
              onClick={() => {
                if (!notification.is_read) {
                  markRead(notification.id);
                }
              }}
              style={{
                textAlign: "left",
                background: notification.is_read ? "transparent" : "rgba(255, 123, 0, 0.08)",
                border: "1px solid #2f3336",
                borderRadius: "12px",
                padding: "16px",
                cursor: "pointer",
              }}
            >
              <div style={{ color: "var(--text-main)", lineHeight: 1.5 }}>{notification.content}</div>
              <div style={{ color: "var(--text-muted)", fontSize: "0.82rem", marginTop: "8px" }}>
                {timeAgo(notification.created_at)}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
